INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Is an End-to-End VPN the same as a Site-to-Site VPN?', 2, '[{"text": "No", "correct": true, "because": "Direct endpoints vs. network gateways"}, {"text": "Yes", "correct": false, "because": "Different configurations"}]'),
('00000000-0000-0000-0000-000000000000', 'What is the primary purpose of an End-to-End VPN?', 3, '[{"text": "Secure data between two specific devices", "correct": true, "because": "End-to-end encryption"}, {"text": "Connect multiple networks", "correct": false, "because": "Site-to-Site focus"}, {"text": "Speed up internet access", "correct": false, "because": "Not the goal"}]'),
('00000000-0000-0000-0000-000000000000', 'Which features characterize an End-to-End VPN?', 5, '[{"text": "Direct encryption between endpoints", "correct": true, "because": "No intermediate decryption"}, {"text": "Point-to-point tunneling", "correct": true, "because": "Secure link"}, {"text": "Centralized server management", "correct": false, "because": "Decentralized"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) An End-to-End VPN encrypts data from source to destination. b) It requires a central gateway.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "No central gateway needed"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore in an End-to-End VPN setup?', 4, '[{"text": "Encryption protocols", "correct": false, "because": "Essential for security"}, {"text": "Endpoint authentication", "correct": false, "because": "Verifies identity"}, {"text": "Paper documentation", "correct": true, "because": "Irrelevant to function"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if an End-to-End VPN always uses public networks?', 2, '[{"text": "No", "correct": true, "because": "Can use private networks"}, {"text": "Yes", "correct": false, "because": "Not mandatory"}]'),
('00000000-0000-0000-0000-000000000000', 'Which protocol is commonly used for End-to-End VPNs?', 3, '[{"text": "IPSec", "correct": true, "because": "Strong encryption"}, {"text": "HTTP", "correct": false, "because": "Web protocol"}, {"text": "FTP", "correct": false, "because": "File transfer"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does an End-to-End VPN offer?', 5, '[{"text": "High security", "correct": true, "because": "End-to-end encryption"}, {"text": "Direct communication", "correct": true, "because": "No intermediaries"}, {"text": "High bandwidth", "correct": false, "because": "Not primary focus"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) End-to-End VPNs secure data between two hosts. b) They need multiple servers. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "No multiple servers"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need for an End-to-End VPN?', 4, '[{"text": "Encryption keys", "correct": false, "because": "Secure connection"}, {"text": "Tunneling protocol", "correct": false, "because": "Data transfer"}, {"text": "Central relay server", "correct": true, "because": "Direct link"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does an End-to-End VPN require a gateway?', 2, '[{"text": "No", "correct": true, "because": "Direct endpoint connection"}, {"text": "Yes", "correct": false, "because": "Not needed"}]'),
('00000000-0000-0000-0000-000000000000', 'Which devices typically use End-to-End VPNs?', 4, '[{"text": "Workstations", "correct": true, "because": "Secure remote access"}, {"text": "Servers", "correct": true, "because": "Direct server links"}, {"text": "Printers", "correct": false, "because": "Not typical"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that End-to-End VPNs are only for large networks. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Also small setups"}, {"text": "Yes", "correct": false, "because": "Flexible use"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize in an End-to-End VPN?', 3, '[{"text": "Security", "correct": true, "because": "Encryption critical"}, {"text": "Color coding", "correct": false, "because": "Irrelevant"}, {"text": "Speed", "correct": false, "because": "Security first"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) End-to-End VPNs encrypt data directly between hosts. b) They rely on intermediate decryption.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "No intermediates"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What technologies support End-to-End VPNs?', 5, '[{"text": "OpenVPN", "correct": true, "because": "Flexible encryption"}, {"text": "IPSec", "correct": true, "because": "Secure tunneling"}, {"text": "FTP", "correct": false, "because": "File transfer"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant for an End-to-End VPN?', 3, '[{"text": "Encryption", "correct": false, "because": "Core feature"}, {"text": "Authentication", "correct": false, "because": "Security"}, {"text": "Paper logs", "correct": true, "because": "Digital sufficient"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Can an End-to-End VPN work over public networks?', 3, '[{"text": "Yes", "correct": true, "because": "Encryption protects"}, {"text": "No", "correct": false, "because": "Designed for it"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if End-to-End VPNs are slower than other VPNs?', 2, '[{"text": "No", "correct": true, "because": "Direct link efficiency"}, {"text": "Yes", "correct": false, "because": "Not inherently slower"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to an End-to-End VPN?', 4, '[{"text": "Direct encryption", "correct": true, "because": "Endpoint security"}, {"text": "Multiple gateways", "correct": false, "because": "Not used"}, {"text": "Paper records", "correct": false, "because": "Irrelevant"}]');
